<?php
namespace App\Console\Commands;
use Illuminate\Console\Command;use Illuminate\Support\Facades\Storage;
class PServiceBackup extends Command{protected $signature='pservice:backup';protected $description='Backup do banco e fotos';public function handle():int{$dir=storage_path('backups');if(!is_dir($dir))mkdir($dir,0750,true);$stamp=now()->format('Y-m-d_H-i-s');$db=config('database.connections.sqlite.database');if(is_file($db))copy($db,"$dir/database_$stamp.sqlite");$zipPath="$dir/photos_$stamp.zip";$zip=new \ZipArchive();if($zip->open($zipPath,\ZipArchive::CREATE|\ZipArchive::OVERWRITE)!==true)return self::FAILURE;$base=Storage::disk('local')->path('photos');if(is_dir($base)){$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($base,\FilesystemIterator::SKIP_DOTS));foreach($it as $file)if($file->isFile())$zip->addFile($file->getPathname(),substr($file->getPathname(),strlen($base)+1));}$zip->close();$cut=now()->subDays((int)env('BACKUP_RETENTION_DAYS',14))->timestamp;foreach(glob($dir.'/*') as $f)if(filemtime($f)<$cut)@unlink($f);$this->info("Backup concluído: $stamp");return self::SUCCESS;}}
